const provider = source.provider ?? source.imageProvider ?? source.image_provider ?? body.provider ?? body.imageProvider ?? body.image_provider ?? $env.AI_IMAGE_PROVIDER ?? 'cloudflare';
const context = {};
const jobId = source.jobId ?? source.job_id ?? body.jobId ?? body.job_id;
const sceneId = source.sceneId ?? source.scene_id ?? source.id ?? body.sceneId ?? body.scene_id ?? body.id;
const sceneIndex = source.sceneIndex ?? source.scene_index ?? body.sceneIndex ?? body.scene_index;
if (jobId !== undefined) context.jobId = jobId;
if (sceneId !== undefined) context.sceneId = sceneId;
if (sceneIndex !== undefined) context.sceneIndex = sceneIndex;
if (typeof prompt !== 'string' || prompt.trim().length === 0) return [{ json: { isValid: false, provider, validationError: { type: 'VALIDATION_ERROR', code: 'MISSING_PROMPT', message: 'prompt is required and must be a non-empty string', source: 'workflow' }, context } }];
return [{ json: { isValid: true, provider, url: null, headers: {}, body: { prompt: prompt.trim() }, context } }];

const source = $input.first()?.json ?? {};
const body = source.body && typeof source.body === 'object' && !Array.isArray(source.body) ? source.body : {};
const rawMetadata = Object.prototype.hasOwnProperty.call(source, 'metadata') ? source.metadata : body.metadata;
const provider = source.provider ?? source.imageProvider ?? source.image_provider ?? body.provider ?? body.imageProvider ?? body.image_provider ?? $env.AI_IMAGE_PROVIDER ?? 'cloudflare';
const prompt = source.prompt ?? body.prompt;
const context = {};
const jobId = source.jobId ?? source.job_id ?? body.jobId ?? body.job_id;
const sceneId = source.sceneId ?? source.scene_id ?? source.id ?? body.sceneId ?? body.scene_id ?? body.id;
const sceneIndex = source.sceneIndex ?? source.scene_index ?? body.sceneIndex ?? body.scene_index;
if (jobId !== undefined) context.jobId = jobId;
if (sceneId !== undefined) context.sceneId = sceneId;
if (sceneIndex !== undefined) context.sceneIndex = sceneIndex;
const invalid = (code, message, sourceName = 'workflow') => [{ json: { isValid: false, provider, url: null, headers: {}, body: null, validationError: { type: sourceName === 'workflow' ? 'VALIDATION_ERROR' : 'PROVIDER_ERROR', code, message, source: sourceName }, context } }];
if (typeof prompt !== 'string' || prompt.trim().length === 0) return invalid('MISSING_PROMPT', 'prompt is required and must be a non-empty string');
if (rawMetadata !== undefined && (rawMetadata === null || typeof rawMetadata !== 'object' || Array.isArray(rawMetadata))) return invalid('INVALID_METADATA', 'metadata must be a plain object');
const SUPPORTED_IMAGE_PROVIDERS = ['gemini', 'cloudflare'];
if (!SUPPORTED_IMAGE_PROVIDERS.includes(provider)) return invalid('UNSUPPORTED_PROVIDER', 'Unsupported image provider: ' + provider);
const accountId = $env.CLOUDFLARE_ACCOUNT_ID;
const model = $env.CLOUDFLARE_IMAGE_MODEL;
const token = $env.CLOUDFLARE_AI_TOKEN;
if (!accountId || !model || !token) return invalid('PROVIDER_CONFIG_MISSING', 'Cloudflare AI credentials are not configured', provider);
return [{ json: { isValid: true, provider, url: 'https://api.cloudflare.com/client/v4/accounts/' + accountId + '/ai/run/' + model, headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' }, body: { prompt: prompt.trim() } } }];

const trigger = $('Workflow Trigger').first()?.json ?? {};
const source = trigger.source && typeof trigger.source === 'object' ? trigger.source : {};
const body = source.body && typeof source.body === 'object' && !Array.isArray(source.body) ? source.body : {};
const metadata = Object.prototype.hasOwnProperty.call(source, 'metadata') ? source.metadata : body.metadata;
const pick = (...values) => values.find(value => value !== undefined && value !== null && value !== '');
const jobId = pick(trigger.jobId, trigger.job_id, source.jobId, source.job_id, metadata?.jobId, metadata?.job_id);
const sceneId = pick(trigger.sceneId, trigger.scene_id, trigger.id, source.sceneId, source.scene_id, source.id, metadata?.sceneId, metadata?.scene_id);
const sceneIndex = pick(trigger.sceneIndex, trigger.scene_index, source.sceneIndex, source.scene_index, metadata?.sceneIndex, metadata?.scene_index);
const requestId = pick(trigger.requestId, trigger.request_id, source.requestId, source.request_id, metadata?.requestId, metadata?.request_id);
const providerId = pick(trigger.providerId, trigger.provider_id, trigger.provider, trigger.imageProvider, trigger.image_provider, trigger.imageProvider, source.providerId, source.provider_id, source.provider, source.imageProvider, source.image_provider, body.providerId, body.provider_id, body.provider, body.imageProvider, body.image_provider, $env.AI_IMAGE_PROVIDER, 'cloudflare');
const modelId = pick(trigger.modelId, trigger.model_id, trigger.imageModel, trigger.image_model, source.modelId, source.model_id, source.imageModel, source.image_model, body.modelId, body.model_id, body.imageModel, body.image_model, $env.CLOUDFLARE_IMAGE_MODEL);
const prompt = pick(trigger.prompt, trigger.image_prompt, trigger.imagePrompt, trigger.visual_prompt, trigger.visualPrompt, source.prompt, source.image_prompt, source.imagePrompt, body.prompt, body.image_prompt, body.imagePrompt);
const output = { jobId, sceneId, sceneIndex, requestId, providerId, modelId, credentialSource: pick(trigger.credentialSource, trigger.credential_source, source.credentialSource, source.credential_source, 'environment'), routingVersion: pick(trigger.routingVersion, trigger.routing_version, source.routingVersion, source.routing_version, '1'), prompt, timeoutMs: Number(pick(trigger.timeoutMs, trigger.timeout_ms, source.timeoutMs, source.timeout_ms, 30000)) };
for (const [sourceName, targetName] of [['width', 'width'], ['height', 'height'], ['seed', 'seed'], ['steps', 'steps']]) { const value = pick(trigger[sourceName], source[sourceName], body[sourceName]); if (value !== undefined) output[targetName] = Number(value); }
return [{ json: output }];

const input = $input.first()?.json ?? {};
const uuidV4 = () => { const bytes = new Uint8Array(16); for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256); bytes[6] = (bytes[6] & 0x0f) | 0x40; bytes[8] = (bytes[8] & 0x3f) | 0x80; return Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('').replace(/^(........)(....)(....)(....)(............)$/, '$1-$2-$3-$4-$5'); };
const attempt = $('Prepare Provider Attempt').last()?.json ?? {};
const retryCount = Number(attempt.retryCount || 0);
return [{ json: { ...input, requestId: retryCount > 0 ? uuidV4() : input.requestId } }];

const input = $input.first()?.json ?? {};
const attempt = $('Prepare Provider Attempt').last()?.json ?? {};
const trigger = $('Workflow Trigger').first()?.json ?? {};
const requestId = input.requestId ?? trigger.requestId ?? trigger.request_id;
const provider = input.provider ?? attempt.provider ?? trigger.provider ?? 'cloudflare';
const model = input.model ?? trigger.modelId ?? trigger.model_id ?? $env.CLOUDFLARE_IMAGE_MODEL ?? null;
const retryable = input.error?.retryable === true;
const failure = (code) => [{ json: { success: false, result: null, provider, model, requestId, statusCode: retryable ? 500 : 400, errors: { code }, retryable } }];
if (input.success !== true) return failure(input.error?.code || 'PROVIDER_RESPONSE_INVALID');
if (input.mimeType && !['image/png', 'image/jpeg'].includes(input.mimeType)) return failure('AI_RESPONSE_INVALID');
try {
  const image = await this.helpers.getBinaryDataBuffer(0, 'image');
  if (!image || image.length === 0) return failure('AI_RESPONSE_EMPTY');
  return [{ json: { success: true, result: { image: image.toString('base64') }, provider, model, requestId, statusCode: 200, errors: null, retryable: false } }];
} catch (error) {
  return failure('AI_RESPONSE_INVALID');
}

const response = $input.first()?.json ?? {};
const attempt = $('Prepare Provider Attempt').last()?.json ?? {};
const retryCount = Number(attempt.retryCount || 0);
const provider = attempt.provider || $('Build Request').first().json.provider;
const providerSuccess = response.success === true && response.result !== undefined;
const statusCode = Number(response.statusCode || 0);
const retryableProvider = ![400, 401, 403, 404].includes(statusCode);
const shouldRetry = !providerSuccess && retryableProvider && retryCount < 2;
const retryExhausted = !providerSuccess && retryableProvider && retryCount >= 2;
const providerError = providerSuccess ? null : { type: 'PROVIDER_ERROR', code: response.errors ? 'PROVIDER_HTTP_ERROR' : 'PROVIDER_RESPONSE_INVALID', message: 'Cloudflare image provider did not return valid image data', retryable: shouldRetry, source: provider };
return [{ json: { providerResponse: response, providerSuccess, providerError, retryCount, shouldRetry, retryExhausted } }];

const input = $input.first().json;
const request = $('Prepare Provider Attempt').last().json;
return [{ json: { ...request, retryCount: Number(input.retryCount || 0) + 1 } }];

const input = $input.first()?.json ?? {};
const trigger = $('Workflow Trigger').first()?.json ?? {};
const provider = input.providerResponse?.provider ?? input.provider ?? 'cloudflare';
const timestamp = new Date().toISOString();
const marker = trigger._testCorrelationId;
const context = {};
const sourceContext = trigger;
const jobId = sourceContext.jobId ?? sourceContext.job_id;
const sceneId = sourceContext.sceneId ?? sourceContext.scene_id ?? sourceContext.id;
const sceneIndex = sourceContext.sceneIndex ?? sourceContext.scene_index;
if (jobId !== undefined) context.jobId = jobId;
if (sceneId !== undefined) context.sceneId = sceneId;
if (sceneIndex !== undefined) context.sceneIndex = sceneIndex;
const base = { success: false, type: 'image', retryCount: Number(input.retryCount || 0), timestamp };
if (Object.keys(context).length) base.context = context;
if (marker !== undefined) base._testCorrelationId = marker;
if (input.isValidationError) { base.error = { ...input.validationError, retryable: false, source: 'workflow' }; return [{ json: base }]; }
if (input.providerSuccess) {
  const image = input.providerResponse?.result?.image;
  if (typeof image !== 'string' || !image) { base.error = { type: 'PROVIDER_ERROR', code: 'PROVIDER_RESPONSE_INVALID', message: 'Cloudflare image provider returned no image data', retryable: false, source: provider }; return [{ json: base }]; }
  const output = { success: true, type: 'image', imageBase64: image, format: 'png', provider: provider, model: $env.CLOUDFLARE_IMAGE_MODEL || null, retryCount: Number(input.retryCount || 0), timestamp };
  if (Object.keys(context).length) output.context = context;
  if (marker !== undefined) output._testCorrelationId = marker;
  return [{ json: output }];
}
base.error = input.retryExhausted ? { type: 'RETRY_EXHAUSTED', code: 'MAX_RETRIES_EXCEEDED', message: 'Provider request failed after the maximum retry count', retryable: false, source: provider || 'workflow' } : (input.providerError || { type: 'PROVIDER_ERROR', code: 'PROVIDER_RESPONSE_INVALID', message: 'Provider request failed', retryable: false, source: provider || 'workflow' });
return [{ json: base }];

const result = $input.first()?.json ?? {};
const evaluated = $('Evaluate Provider Result').last()?.json ?? {};
const trigger = $('Workflow Trigger').first()?.json ?? {};
const requestId = result.requestId ?? evaluated.providerResponse?.requestId ?? trigger.requestId ?? trigger.request_id;
return [{ json: requestId === undefined ? result : { ...result, requestId } }];
